window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-13991\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνσκίμπτω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2752 na letra ε · nº geral 13991</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐνισκίμπτω (aor. ἐνέσκιμψα; aor. pas. 3ª sing. poét. ἐνισκίμφθη) 1 apoiar sobre, dat. 2 lançar em, dat.</p></section></article>\n<article id=\"entry-dgp-13992\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔνσπονδος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2753 na letra ε · nº geral 13992</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 incluído num tratado (trégua, aliança) 2 aliado de, gen. ou dat. 3 protegido por pacto; sob salvaguarda 4 bem disposto para alguém, πρός e ac. 〈ἐν, σπονδή〉</p></section></article>\n<article id=\"entry-dgp-13993\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνστάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2754 na letra ε · nº geral 13993</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer gotejar; escorrer em; verterem ou sobre, dat. 2 inspirar; infundir algo, ac., em alguém, dat.</p></section></article>\n<article id=\"entry-dgp-13994\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνσταλάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2755 na letra ε · nº geral 13994</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐνστάζω.</p></section></article>\n<article id=\"entry-dgp-13995\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔνστασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2756 na letra ε · nº geral 13995</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 início de um empreendimento; instituição; instauração 2 ação de pressionar 3 oposição; objeção. 〈ἐνίστημι〉</p></section></article>\n<article id=\"entry-dgp-13996\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνστάτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 2757 na letra ε · nº geral 13996</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que se opõe; adversário. 〈ἐνίστημι〉</p></section></article>\n<article id=\"entry-dgp-13997\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνστατικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2758 na letra ε · nº geral 13997</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que opõe resistência 2 que cria obstáculo; que barra; que impede, gen. 3 pronto para fazer objeção; polêmico. 〈ἐνίστημι〉</p></section></article>\n<article id=\"entry-dgp-13998\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνστέλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 2759 na letra ε · nº geral 13998</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">envolver com; revestir algo, ac., de, ac.</p></section></article>\n<article id=\"entry-dgp-13999\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔνστημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2760 na letra ε · nº geral 13999</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">obstáculo; objeção. 〈ἐνίστημι〉</p></section></article>\n<article id=\"entry-dgp-14000\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνστηρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2761 na letra ε · nº geral 14000</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">encravar em ou apoiar sobre; fixar em, dat.</p></section></article>\n<article id=\"entry-dgp-14001\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνστήσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2762 na letra ε · nº geral 14001</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. ind. méd. de ἐνίστημι.</p></section></article>\n<article id=\"entry-dgp-14002\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνστρατοπεδεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2763 na letra ε · nº geral 14002</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">acampar em, ἐν e dat.</p></section></article>\n<article id=\"entry-dgp-14003\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνστρέφω</h1><div class=\"entry-meta\"><span>DGP · ordem 2764 na letra ε · nº geral 14003</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer dar a volta em ♦ pas. 2 mover-se contornando ou contornar, dat.</p></section></article>\n<article id=\"entry-dgp-14004\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔνταλμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2765 na letra ε · nº geral 14004</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. mandamento; preceito. 〈ἐντέλλω〉</p></section></article>\n<article id=\"entry-dgp-14005\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντάμνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2766 na letra ε · nº geral 14005</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἐντέμνω.</p></section></article>\n<article id=\"entry-dgp-14006\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντανύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2767 na letra ε · nº geral 14006</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. e jôn. 1 esticar fortemente (arco) ♦ méd. 2 esticar (seu arco).</p></section></article>\n<article id=\"entry-dgp-14007\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2768 na letra ε · nº geral 14007</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tensão; rigidez; sisudez 2 intensidade; contenção; esforço 3 inclusão; inserção (em círculo). 〈ἐντείνω〉</p></section></article>\n<article id=\"entry-dgp-14008\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντάσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2769 na letra ε · nº geral 14008</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -τάττω 1 dispor em fileiras 2 dispor contra; opor a, dat.</p></section></article>\n<article id=\"entry-dgp-14009\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνταῦθα</h1><div class=\"entry-meta\"><span>DGP · ordem 2770 na letra ε · nº geral 14009</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 (lugar) aqui; ali mesmo: ἐντ. τῆς ἠπείρου tuc. neste lugar do continente, ἐντ. ἀφικόμην κακοῦ ésql. cheguei a este grau de infelicidade 2 (tempo) naquele momento; então: ὅτε ἐντ. quando então, ἐντ. ἤδη εἶ ἡλικίας plat. já estás naquela idade. 〈ἔνθα, αὐτός〉</p></section></article>\n<article id=\"entry-dgp-14010\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνταυθί</h1><div class=\"entry-meta\"><span>DGP · ordem 2771 na letra ε · nº geral 14010</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = ἐνταῦθα.</p></section></article>\n<article id=\"entry-dgp-14011\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνταυθοῖ</h1><div class=\"entry-meta\"><span>DGP · ordem 2772 na letra ε · nº geral 14011</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. aqui.</p></section></article>\n<article id=\"entry-dgp-14012\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνταφιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2773 na letra ε · nº geral 14012</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">preparar para o sepultamento. 〈ἐντάφιος〉</p></section></article>\n<article id=\"entry-dgp-14013\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνταφιασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2774 na letra ε · nº geral 14013</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. sepultamento. 〈ἐνταφιάζω〉</p></section></article>\n<article id=\"entry-dgp-14014\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντάφιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2775 na letra ε · nº geral 14014</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se refere ao enterro ou aos funerais; funerário; fúnebre ♦ τὸ ἐντάφιον 2 mortalha; sudário ♦ τὰ ἐντάφια 3 ritos fúnebres; exéquias. 〈ἐν, τάφος1〉</p></section></article>\n<article id=\"entry-dgp-14015\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντεα,</h1><div class=\"entry-meta\"><span>DGP · ordem 2776 na letra ε · nº geral 14015</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. ἔντη cf. ἔντος.</p></section></article>\n<article id=\"entry-dgp-14016\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντεῖλαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2777 na letra ε · nº geral 14016</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. de ἐντέλλω.</p></section></article>\n<article id=\"entry-dgp-14017\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντείνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2778 na letra ε · nº geral 14017</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 esticar: ἐντ. ἵππον τῷ ἀγωγεῖ xen. puxar o cavalo com a rédea 2 manter; submeter: βοῦν ἢ λέοντ᾽ ἤλπιζες ἐντείνεν βρόχοις; eur. esperavas submeter um boi ou um leão com cordas? 3 esticar sobre; revestir; lançar sobre: ἐντ. τὸν θρόνον her. revestir o assento, ἔτι γὰρ ἐδόκεον ἐντεταμένας εὐρήσειν γεφύρας her. esperavam encontrar ainda esticadas as pontes 4 submeter ao verso: ἐντ. νόμους εἰς ἔπος plut. versificar as leis (lit. submeter as leis à medida dos versos), ἐντ. τοὺς τοῦ Αἰσώπου λόγους plat. versificar as fábulas de Esopo 5 estender contra; atacar; intensificar: πληγὰς ἐνέτεινον ἀλλήλοις xen. davam golpes uns nos outros, εἴ τις ἐντείναι τὴν πολιορκίαν plut. se se intensificasse o assédio, πρόσωπον ἐντεταμένον luc. rosto rígido, i.e., de aspecto sério ou severo 6 entesar-se; ser veemente ou violento; esticar fortemente ♦ méd. 7 esticar (o arco) 8 manter esticado, tenso (acorde, voz): ἐντεταμένος εἶπον plat. tenso, falei 9 manter a atenção em; aplicar-se intensamente a, εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-14018\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντειχίδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2779 na letra ε · nº geral 14018</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rodeado de muros; amuralhado. 〈ἐν­τειχίζω〉</p></section></article>\n<article id=\"entry-dgp-14019\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντειχίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2780 na letra ε · nº geral 14019</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 construir fortificações em, ἐν e dat. 2 fortificar, ac. ♦ méd. 3 murar; bloquear 4 construir fortes; fortificar.</p></section></article>\n<article id=\"entry-dgp-14020\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντεκνόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2781 na letra ε · nº geral 14020</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐντεκνώσομαι) gerar filhos; dar à luz. 〈ἐν, τέκνον〉</p></section></article>\n<article id=\"entry-dgp-14021\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντεκνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2782 na letra ε · nº geral 14021</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem filhos. 〈ἐν, τέκνον〉</p></section></article>\n<article id=\"entry-dgp-14022\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντελευτάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2783 na letra ε · nº geral 14022</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">findar em; morrer em, dat.</p></section></article>\n<article id=\"entry-dgp-14023\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντελής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 2784 na letra ε · nº geral 14023</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acabado; realizado 2 plenamente desenvolvido (pessoa) 3 inteiro; completo (coisa) 4 sem defeito; em perfeito estado 5 bem equipado (soldado, navio). 〈ἐν, τέλος〉</p></section></article>\n<article id=\"entry-dgp-14024\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντέλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 2785 na letra ε · nº geral 14024</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐνέτειλα; perf. pas. ἐντέταλμαι) 1 recomendar; comandar; ordenar: τὰ ἐντεταλμένα as ordens, as instruções ♦ méd. 2 ordenar a alguém, dat., algo, ac. ou inf.</p></section></article>\n<article id=\"entry-dgp-14025\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντέμνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2786 na letra ε · nº geral 14025</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 talhar em; entalhar: ἐντ. γράμματα ἐν λίθοις her. gravar letras nas pedras 2 cortar: ἐντ. ἄκος ésql. preparar remédio (lit. cortar planta medicinal), ἐντ. τὸν λαιμόν luc. cortar a garganta, ἐντ. σφάγιά τινι degolar uma vítima em honra de alguém ♦ méd. 3 imolar.</p></section></article>\n<article id=\"entry-dgp-14026\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντερον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2787 na letra ε · nº geral 14026</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ger. pl., intestino 2 ventre; útero 3 víscera 4 interior de um fruto ♦ τὰ ἔντερα γῆς 5 lombrigas. 〈ἐντός〉</p></section></article>\n<article id=\"entry-dgp-14027\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντεσιεργός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2788 na letra ε · nº geral 14027</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que trabalha arreado (animal de tração). 〈ἐντός, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-14028\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντεταμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 2789 na letra ε · nº geral 14028</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com tensão; com força. 〈ἐντείνω〉</p></section></article>\n<article id=\"entry-dgp-14029\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντέτατο</h1><div class=\"entry-meta\"><span>DGP · ordem 2790 na letra ε · nº geral 14029</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. m.-q.-perf. poét. de ἐντείνω.</p></section></article>\n<article id=\"entry-dgp-14030\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντεῦθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 2791 na letra ε · nº geral 14030</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 (lugar) daqui; daí 2 (lugar) aqui: τἀντεῦθεν as coisas daqui, i.e., o que se passa nesta casa, ἐντεῦθεν καὶ ἐν­τεῦθεν bíbl. de um lado e de outro 3 (tempo) a partir de agora; desde já: τὸ ἐντεῦθεν, τὰ ἐντεῦθεν, τἀντεῦθεν desde já, doravante 4 (origem ou causa) a partir disto; a partir desta causa 5 por conseguinte; em conseqüência. 〈ἐνταῦθα, -θεν〉</p></section></article>\n<article id=\"entry-dgp-14031\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντευθενί</h1><div class=\"entry-meta\"><span>DGP · ordem 2792 na letra ε · nº geral 14031</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = ἐντεῦθεν.</p></section></article>\n<article id=\"entry-dgp-14032\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντευκτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2793 na letra ε · nº geral 14032</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de comunicação fácil; afável. 〈ἐν­τυγχάνω〉</p></section></article>\n<article id=\"entry-dgp-14033\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντευξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2794 na letra ε · nº geral 14033</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 encontro com alguém, dat. 2 entrevista; colóquio com algém, gen. ou πρός e ac.: ἐντεύξεις ποιεῖσθαί τινι isócr. reunir-se com alguém, ter entrevistas ou uma entrevista com alguém 3 relações íntimas 4 discurso; pronunciamento 5 tard. requerimento; pedido; petição 6 súplica; prece 7 tard. leitura. 〈ἐντυγχάνω〉</p></section></article>\n<article id=\"entry-dgp-14034\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντεχνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2795 na letra ε · nº geral 14034</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que é do domínio da arte; artesenal; artístico 2 hábil; industrioso 3 feito ou trabalhado com arte, conforme as regras da arte. 〈ἐν, τέχνη〉</p></section></article>\n<article id=\"entry-dgp-14035\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντήκω</h1><div class=\"entry-meta\"><span>DGP · ordem 2796 na letra ε · nº geral 14035</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer fundir em; fazer fluir; escoar uma matéria fundida em, dat. ♦ perf. ἐντέτηκα 2 escoar-se em; infundir-se em 3 (sentimentos) ter penetrado em, dat. ♦ pas. (aor.2 ἐνετάκην) 4 fundir-se 5 consumir-se: ἐντ. τῷ φιλεῖν sóf. consumir-se por amor.</p></section></article>\n<article id=\"entry-dgp-14036\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντί</h1><div class=\"entry-meta\"><span>DGP · ordem 2797 na letra ε · nº geral 14036</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. e 3ª pl. pres. dór. de εἰμί.</p></section></article>\n<article id=\"entry-dgp-14037\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντιθέμεσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2798 na letra ε · nº geral 14037</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1ª pl. poét. impf. méd. de ἐντίθημι.</p></section></article>\n<article id=\"entry-dgp-14038\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντίθημι</h1><div class=\"entry-meta\"><span>DGP · ordem 2799 na letra ε · nº geral 14038</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐνθήσω) 1 pôr em; colocar em, dat. ou εἰς e ac.: ἐντ. αὐχένα ζυγῷ eur. entregar o pescoço ao jugo, ἐς τὼ κοθόρνω τὼ πόδ᾽ ἐνθείς artt. tendo enfiado os pés no coturno, δέλτα ἐνθεὶς ἀντὶ τοῦ νῦ plat. colocando um delta no lugar do ni 2 infundir; incutir: ἐντ. φόβον xen. infundir medo 3 colocar a bordo; embarcar: ἐντ. οἶνον hom. embarcar vinho 4 pôr sobre: ἐντ. χλαίνας hom. estender mantas (sobre uma cama), ἐντ. κόσμον τάφῳ eur. enfeitar um túmulo ♦ méd. 5 colocar para si em ou sobre: ἐντ. τινὰ λεχέεσι hom. colocar alguém em ou sobre o leito, ἐντ. τι εἰς τὸ πλοῖον xen. colocar algo num navio, ἐντ. χόλον θυμῷ hom. conceber a cólera no peito, παιδὸς γὰρ μῦθον πεπνυμένον ἔνθετο θυμῷ hom. acolheu no coração a sábia palavra do filho, ἐντ. τινὰ τιμῇ hom. incluir alguém em sua estima 6 embarcar.</p></section></article>\n<article id=\"entry-dgp-14039\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντίκτω</h1><div class=\"entry-meta\"><span>DGP · ordem 2800 na letra ε · nº geral 14039</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐντέξομαι) 1 parir em; gerar em, dat. ou ἐν e dat. 2 dar cria 3 engendrar; conceber (sabedoria, sentimento) ♦ ἐντετοκώς, υῖα, ός part. perf. 4 nascido em; gerado em.</p></section></article>\n<article id=\"entry-dgp-14040\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2801 na letra ε · nº geral 14040</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estimado; considerado; honrado junto a alguém, dat. ou παρά e dat., por causa de algo, dat. 2 que tem valor; valioso; válido; corrente (moeda): τὰ τῶν θεῶν ἔντιμα sóf. o que é valorizado pelos deuses, seus atributos ou preceitos 3 que traz honra: λόγος ἔντ. λεγόμενος plat. honrosa reputação ♦ οἱ ἔντιμοι 4 os honoráveis 5 as pessoas de alto escalão; as pessoas distintas, entre os persas. 〈ἐν, τιμή〉</p></section></article>\n<article id=\"entry-dgp-14041\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντιμότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2802 na letra ε · nº geral 14041</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">honra; valor; mérito. 〈ἔντιμος〉</p></section></article>\n<article id=\"entry-dgp-14042\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντίμως</h1><div class=\"entry-meta\"><span>DGP · ordem 2803 na letra ε · nº geral 14042</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com honra; honradamente; ἐντ. ἔχειν xen. ser honrado, ἐντ. ἔχειν ou ἄγειν τινά plat. honrar alguém.</p></section></article>\n<article id=\"entry-dgp-14043\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕντο</h1><div class=\"entry-meta\"><span>DGP · ordem 2804 na letra ε · nº geral 14043</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. aor. méd. poét. de ἵημι.</p></section></article>\n<article id=\"entry-dgp-14044\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντολή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2805 na letra ε · nº geral 14044</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ordem; instrução; mandamento. 〈ἐντέλλω〉</p></section></article>\n<article id=\"entry-dgp-14045\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2806 na letra ε · nº geral 14045</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cortado em pedaços; talhado ♦ τὰ ἔντομα 2 [σφάγια] vítimas oferecidas aos manes 3 [ζῷα] insetos. 〈ἐντέμνω〉</p></section></article>\n<article id=\"entry-dgp-14046\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντονος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2807 na letra ε · nº geral 14046</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fortemente tenso; vigoroso; veemente; violento ♦ ὁ ἔντονος 2 tensão. 〈ἐντείνω〉</p></section></article>\n<article id=\"entry-dgp-14047\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντόνως</h1><div class=\"entry-meta\"><span>DGP · ordem 2808 na letra ε · nº geral 14047</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com tensão; com força; com vigor.</p></section></article>\n<article id=\"entry-dgp-14048\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντόπιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2809 na letra ε · nº geral 14048</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">do país; local; nativo. 〈ἔντοπος〉</p></section></article>\n<article id=\"entry-dgp-14049\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντοπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2810 na letra ε · nº geral 14049</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do lugar; local; nativo ♦ οἱ ἔντοποι 2 habitantes de um país. 〈ἐν, τόπος〉</p></section></article>\n<article id=\"entry-dgp-14050\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντορεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2811 na letra ε · nº geral 14050</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">talhar em relevo; cinzelar.</p></section></article>\n<article id=\"entry-dgp-14051\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2812 na letra ε · nº geral 14051</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ger. pl. ἔντεα, contr. ἔντη 1 armas; armadura 2 cota de malhas; couraça 3 equipamento; guarnição: ἔ. δαιτός hom. baixela de uma refeição, ἔ. νηός hom. equipagem naval, ἔντεα ἵππεια pínd. arreios de cavalo. 〈ἕννυμι〉</p></section></article>\n<article id=\"entry-dgp-14052\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντός</h1><div class=\"entry-meta\"><span>DGP · ordem 2813 na letra ε · nº geral 14052</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prep. com gen. 1 (lugar) dentro; no interior de: ἐ. ποιεῖσθαι ou ποιεῖν receber no interior de, ἐ. ἑωυτοῦ γίνεσθαι her. tornar a ser senhor de si, ἐ. λογισμῶν εἶναι dem. ser senhor de si, estar em seu bom senso, ἐ. ἰέναι plut. ir ao interior de 2 (lugar) para trás de ou em recuo: ἐ. τείχεος hom. para trás ou dentro do muro 3 (lugar) deste lado de: ἐ. τοῦ ποταμοῦ her. deste lado do rio, ἐ. τοξεύματος xen. ao alcance do dardo 4 (tempo) no limite de ou em menos de: ἐ. εἴκοσιν ἡμερῶν tuc. em menos de vinte dias, ἐ. ἑσπέρας xen. no máximo até à tarde 5 no limite de ou menos de: ἐ. δραχμῶν πεντέκοντα plat. menos de cinqüenta dracmas ♦ τὰ ἐντός 6 o interior do corpo 7 o que é interno ao homem; inteligência; reflexão.</p></section></article>\n<article id=\"entry-dgp-14053\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντοσθε</h1><div class=\"entry-meta\"><span>DGP · ordem 2814 na letra ε · nº geral 14053</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, diante de vogal, ἔντοσθεν adv. 1 do interior; no interior ♦ prep. com gen. 2 no interior de; dentro de. 〈ἐντός, -θε(ν)〉</p></section></article>\n<article id=\"entry-dgp-14054\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντόσθια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 2815 na letra ε · nº geral 14054</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">intestinos; entranhas. 〈ἔντοσθε〉</p></section></article>\n<article id=\"entry-dgp-14055\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντραγεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 2816 na letra ε · nº geral 14055</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de ἐντρώγω.</p></section></article>\n<article id=\"entry-dgp-14056\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντραγῳδέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2817 na letra ε · nº geral 14056</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">declamar com ênfase trágica diante de, dat.</p></section></article>\n<article id=\"entry-dgp-14057\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντραπῇ, ἐντραπήσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2818 na letra ε · nº geral 14057</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. aor.2 e ind. fut.2 pas. de ἐντρέπω.</p></section></article>\n<article id=\"entry-dgp-14058\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντρεπτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2819 na letra ε · nº geral 14058</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que envergonha; que causa acanhamento 2 acanhado; recatado; tímido. 〈ἐντρέπω〉</p></section></article>\n<article id=\"entry-dgp-14059\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντρέπω</h1><div class=\"entry-meta\"><span>DGP · ordem 2820 na letra ε · nº geral 14059</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 retornar; voltar; virar: ἐντ. τὰ νῶτα her. dar as costas para fugir 2 mudar; alterar (sentimento) ♦ méd. 3 deixar-se comover ou enternecer 4 preocupar-se com alguém ou algo, gen. ou inf. 5 sentir vergonha ou respeito diante de, ac. 6 sentir-se envergonhado.</p></section></article>\n<article id=\"entry-dgp-14060\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντρέφω</h1><div class=\"entry-meta\"><span>DGP · ordem 2821 na letra ε · nº geral 14060</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐνθρέψω) 1 alimentar; nutrir; criar alguém, ac., em, dat. ♦ méd. 2 cultivar.</p></section></article>\n<article id=\"entry-dgp-14061\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντρέχεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2822 na letra ε · nº geral 14061</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">diligência; habilidade. 〈ἐντρεχής〉</p></section></article>\n<article id=\"entry-dgp-14062\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντρεχής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 2823 na letra ε · nº geral 14062</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">diligente; hábil; ágil. 〈ἐντρέχω〉</p></section></article>\n<article id=\"entry-dgp-14063\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντρέχω</h1><div class=\"entry-meta\"><span>DGP · ordem 2824 na letra ε · nº geral 14063</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐνδραμοῦμαι, aor.2 ἐνέδραμον) 1 correr em ou entre, dat. 2 deslizar em, dat. 3 mover-se livre em.</p></section></article>\n<article id=\"entry-dgp-14064\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντρεχῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 2825 na letra ε · nº geral 14064</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com diligência; habilmente.</p></section></article>\n<article id=\"entry-dgp-14065\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντριβής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 2826 na letra ε · nº geral 14065</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">exercitado; habituado a; calejado em algo, dat. ou περί e ac. 〈ἐντρίβω〉</p></section></article>\n<article id=\"entry-dgp-14066\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντρίβω</h1><div class=\"entry-meta\"><span>DGP · ordem 2827 na letra ε · nº geral 14066</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 friccionar ♦ méd. 2 ungir ou maquilar: ἐντ. φυκίον τῷ προσώπῳ luc. espalhar cosmético no rosto, ἐντε­τριμμένος maquilado, ἐντετριμμένος ψιμυθίῳ xen. ou χρῶματα luc. coberto de cosmético 3 assentar; aplicar algo, ac., em alguém ou algo, dat.: ἐντ. κακόν τινι luc. fazer mal a alguém, ἐντ. κονδύλους τινί plut. dar uma esfrega, i.e., uma sova em alguém.</p></section></article>\n<article id=\"entry-dgp-14067\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντριμμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2828 na letra ε · nº geral 14067</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cosmético. 〈ἐντρίβω〉</p></section></article>\n<article id=\"entry-dgp-14068\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντρίχωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2829 na letra ε · nº geral 14068</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tipo de peneira de crina. 〈ἐν, θρίξ〉</p></section></article>\n<article id=\"entry-dgp-14069\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντριψις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2830 na letra ε · nº geral 14069</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de ungir; unção 2 ação de maquilar 3 cosmético. 〈ἐντρίβω〉</p></section></article>\n<article id=\"entry-dgp-14070\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντρομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2831 na letra ε · nº geral 14070</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que treme todo. 〈ἐν, τρέμω〉</p></section></article>\n<article id=\"entry-dgp-14071\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντροπαλίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2832 na letra ε · nº geral 14071</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. pres.) voltar-se de quando em quando para olhar para trás ao fugir. 〈ἐντρέπω〉</p></section></article>\n<article id=\"entry-dgp-14072\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντροπή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2833 na letra ε · nº geral 14072</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de retrair-se por vergonha ou temor; pudor; acanhamento 2 respeito. 〈ἐντρέπω〉</p></section></article>\n<article id=\"entry-dgp-14073\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔντροφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2834 na letra ε · nº geral 14073</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 nutrido em; que cresce em; que vive em, dat.: ἔντ. μόχθῳ sóf. criado no sofrimento, ἔντ. παλαιᾷ ἁμέρᾳ sóf. avançado em idade ♦ ὁ ἔντροφος 2 cria de, gen. 〈ἐντρέφω〉</p></section></article>\n<article id=\"entry-dgp-14074\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντρυφάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2835 na letra ε · nº geral 14074</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 comprazer-se; deleitar-se em, dat. ou ἐν e dat. 2 entregar-se à moleza, à languidez 3 zombar; caçoar de, dat. ♦ pas. 4 ser caçoado ou insultado.</p></section></article>\n<article id=\"entry-dgp-14075\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντρώγω</h1><div class=\"entry-meta\"><span>DGP · ordem 2836 na letra ε · nº geral 14075</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só aor.2 ἐνέτραγον, inf. aor.2 ἐντραγεῖν) engolir gulosamente.</p></section></article>\n<article id=\"entry-dgp-14076\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντυγχάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2837 na letra ε · nº geral 14076</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐντεύξομαι) 1 cruzar por acaso com; encontrar no seu caminho alguém ou algo, dat. ou gen. 2 (raio, infelicidade) cair sobre alguém, dat. 3 encontrar-se com; ter uma entrevista, um encontro com, dat. 4 ter relação íntimas com, dat. 5 ter familiaridade com um livro 6 tard. ler: οἱ ἐντυγχάνοντες pol. os leitores 7 interceder junto a; solicitar a alguém, dat., por alguém, ὑπέρ e gen., algo, inf. ou or. conj. (ὅπως).</p></section></article>\n<article id=\"entry-dgp-14077\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντυλίσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2838 na letra ε · nº geral 14077</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -ίττω (aor. ἐνετύλιξα) envolver em, dat.</p></section></article>\n<article id=\"entry-dgp-14078\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2839 na letra ε · nº geral 14078</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ép. ἔντυνον, fut. ἐντυνῶ, aor. ép. ἔντυνα, perf. desus.) 1 guarnecer; equipar; preparar: ἐντ. ἵππους eur. atrelar cavalos, ἐντ. λέχος a.r. preparar um leito, ἐντ. ἀοιδήν hom. compor um canto, ἐντ. δέπας hom. preparar uma taça, i.e., encher com vinho 2 preparar; dispor; exortar alguém, ac., a, inf. ♦ méd. 3 equipar-se; preparar-se 4 preparar para si (refeição) 5 cumprir (promessa).</p></section></article>\n<article id=\"entry-dgp-14079\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντυπάς</h1><div class=\"entry-meta\"><span>DGP · ordem 2840 na letra ε · nº geral 14079</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. envolvendo-se ou enrolando-se em algo, ἐν e dat., de maneira a moldar as formas do corpo. 〈ἐν, τύπος〉</p></section></article>\n<article id=\"entry-dgp-14080\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντυπόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2841 na letra ε · nº geral 14080</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">imprimir em, dat. ou εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-14081\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντυχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2842 na letra ε · nº geral 14081</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 encontro; conversa 2 súplica 3 acusação. 〈ἐντυγχάνω〉</p></section></article>\n<article id=\"entry-dgp-14082\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐντύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2843 na letra ε · nº geral 14082</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐντύνω.</p></section></article>\n<article id=\"entry-dgp-14083\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐνυάλιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2844 na letra ε · nº geral 14083</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">templo de Eniálio. 〈 Ἐνυάλιος〉</p></section></article>\n<article id=\"entry-dgp-14084\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐνυάλιος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2845 na letra ε · nº geral 14084</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Eniálio, sobrenome de Ares: τῷ Ἐνυαλίῳ ἐλελίζειν ou ἀλαλάζειν xen. dar o grito de guerra em honra a Eniálio.</p></section></article>\n<article id=\"entry-dgp-14085\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνυβρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2846 na letra ε · nº geral 14085</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ultrajar; insultar alguém, ac., em, dat. ou εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-14086\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνύβρισμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2847 na letra ε · nº geral 14086</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ultraje; insulto; maus tratos 2 vítima de ultraje. 〈ἐνυβρίζω〉</p></section></article>\n<article id=\"entry-dgp-14087\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔνυδρις, ιος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2848 na letra ε · nº geral 14087</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lontra. 〈ἐν, ὕδωρ〉</p></section></article>\n<article id=\"entry-dgp-14088\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνυδρίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2849 na letra ε · nº geral 14088</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἔνυδρις.</p></section></article>\n<article id=\"entry-dgp-14089\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔνυδρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2850 na letra ε · nº geral 14089</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 abundante em água 2 que dá na água; aquático 3 submerso em água ♦ ὁ ἔνυδρος 4 lontra ♦ τὰ ἔνυδρα 5 seres aquáticos (animais ou plantas). 〈ἐν, ὕδωρ〉</p></section></article>\n<article id=\"entry-dgp-14090\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔνυξα</h1><div class=\"entry-meta\"><span>DGP · ordem 2851 na letra ε · nº geral 14090</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de νύσσω.</p></section></article>\n";
